insert into public.sections (id, label, sort, data)
values
  ('meta', 'Site title', 0, '{"title":"Phone Hustlers â€” Call Center","description":"Phone Hustlers is a call center on VICIdial. Our predictive dialer lets each caller make hundreds of calls in a shift. We explain the offer and book the next step."}'::jsonb),
  ('site', 'Menu, footer, and buttons', 1, '{"cal":"https://cal.com/","email":"inquires@phonehustler.com","emailLabel":"Email Us","phone":"+63 945 620 6543","phoneTel":"+639456206543","inquiryTitle":"Talk to us","inquiryText":"Let us know exactly what you offer, and what you want to gain by using our phone services.","inquiryAside":"Contact us any time, 24/7","inquiryButton":"Send my details","inquiryThanks":"We got your note. We will call you soon.","navButton":"Book a Call","menuOpen":"Menu","menuClose":"Close","exploreLabel":"Explore","socialsLabel":"Socials","copyright":"Â©2026 Phone Hustlers.","credit":"Built by Apex Technology","footerBlurb":"Every business is different. We take the time to understand your goals, reach the right audience, and create an approach that works for your business.","ctaTitle":"Turn More Conversations Into Customers","ctaBody":"Every call is an opportunity to grow your business. We focus on reaching the right people, building meaningful connections, and turning promising conversations into real opportunities.\n\nPhone Hustlers â€” More Connections. More Opportunities. More Growth.","ctaPeople":"Our callers","ctaButton":"Book a Call","nav":[{"label":"Home","to":"/"},{"label":"Industries","to":"/#services"},{"label":"Our Work","to":"/case-studies"},{"label":"About","to":"/about-us"},{"label":"Articles","to":"/blog"}],"footerLinks":[{"label":"Industries","to":"/#services","external":false},{"label":"Our Work","to":"/case-studies","external":false},{"label":"Process","to":"/#steps-cta-section","external":false},{"label":"About","to":"/about-us","external":false},{"label":"Contact Us","to":"https://cal.com/","external":true},{"label":"404","to":"/404","external":false}],"socials":[{"label":"X/Twitter","to":"https://x.com/home"},{"label":"Youtube","to":"https://www.youtube.com/"},{"label":"Instagram","to":"https://www.instagram.com/"},{"label":"Linkedin","to":"https://www.linkedin.com"}]}'::jsonb),
  ('hero', 'Home banner', 2, '{"kicker":"Phone Hustlers","before":"Finding You ","accent":"Customers That Convert","after":".","lead":"We know the phone. We know the game. And we know how to get results.","sub":"","button":"Book a Call","banner":"/hero.jpg?v=2","bannerAlt":"A Phone Hustlers specialist on a headset, lit against a dark office","name":"Jay Bendebel","role":"CEO at Phone Hustlers","talk":"Talk to us","image":"/jay-benz.jpg"}'::jsonb),
  ('aboutHome', 'Home about strip', 3, '{"tag":"About Us","trusted":"Trusted by the companies we call for","stars":"â˜…â˜…â˜…â˜…â˜…","headline":"Stop dialing one number at a time. Our automated calling system handles hundreds of calls per shift, helping you maximize your return on investment.","fade":"Phone Hustlers â€” Less Waiting. More Calling. More Conversions.","button":"Read More","buttonTo":"/about-us","videoImage":"https://images.unsplash.com/photo-1557804506-669a67965ba0?auto=format&fit=crop&w=1400&q=80","quote":"In a few weeks, people who wanted help started booking time with us. The calls were easy to follow.","quoteName":"Alice Miller","quoteRole":"Owner, solar company","quoteImage":"https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=120&q=80","logos":["Solar","Medicare","Auto Insurance","Business Loans","Final Expense","Medical Alert","Security"],"faces":["/jay-benz.jpg","https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=200&q=80","https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?auto=format&fit=crop&w=200&q=80","https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=200&q=80"],"stats":[{"label":"Calling teams trained","value":1500,"suffix":"+","prefix":""},{"label":"More appointments booked","value":87,"suffix":"%","prefix":""},{"label":"Sales our callers helped","value":30,"suffix":"M+","prefix":"$"},{"label":"Calls handled","value":4.2,"suffix":"M","prefix":""}]}'::jsonb),
  ('dialer', 'VICIdial dialer', 4, '{"tag":"The Dialer","title":"Multiple numbers called at once","fade":"","body":"A normal phone calls one number and waits. VICIdial calls multiple numbers at the same time. Rings and busy tones stay on the computer. A caller joins only when a real person picks up. That is how one person can make hundreds of calls in a shift.","photo":"https://images.unsplash.com/photo-1556761175-5973dc0f32e7?auto=format&fit=crop&w=1600&q=80","button":"Put my list on VICIdial","oldLabel":"The old way","oldTitle":"One number at a time","oldPoints":["Calls one number, then waits","Busy tones and voicemail eat the shift","Only a few dozen real talks"],"kicker":"Predictive dialer","name":"VICIdial","pitch":"Our VICIdial calls multiple numbers at once and our caller only hears â€œHOLLOâ€.","stat":"Hundreds","statLabel":"of calls from one caller, in one shift","lines":["Number 1","Number 2","Number 3","Number 4","Number 5"],"ringLabel":"Dialing","liveLabel":"Picked up","points":["Multiple numbers called at once","Skips most answering machines","Skips dead numbers","Live customer call every 30 to 45 seconds"],"steps":[{"title":"Load the list","body":"We put the names into VICIdial. You do not buy a dialer."},{"title":"Call them together","body":"It calls multiple numbers at once. Empty lines stay on the computer, not on the caller."},{"title":"Talk and book","body":"The rep explains the offer and sets the next step."}]}'::jsonb),
  ('solution', 'How we help', 5, '{"tag":"Our Solution","title":"The Dialer That Keeps","fade":"Every Caller Talking","chart":"More live answers","photo":"/filipino-call-center.jpg?v=1","items":[{"title":"VICIdial dials for us","body":"It is a predictive dialer. It calls multiple numbers at once. A caller joins only when a real person picks up.","icon":"page"},{"title":"Hundreds of calls a shift","body":"One rep is not stuck listening to rings. They spend the shift talking, so one person can reach hundreds of people.","icon":"layers"},{"title":"We book the next step","body":"A good call ends with a time on the calendar, a clear no, or a note about what the person still needs.","icon":"route"}]}'::jsonb),
  ('workHome', 'Home lead delivery', 6, '{"tag":"Your leads","title":"How to receive your leads & appointments","notes":"Special notes: this is how you receive each appointment or customer lead from our callers. Choose the handoff that fits your business.","intro":"How do you want your leads?","options":[{"title":"Text message directly to you?","body":"Lead details sent to your phone by SMS—the name, number, and notes from the call.","image":"/lead-delivery-sms.jpg?v=1"},{"title":"Transfer the call live to you?","body":"We qualify the customer on the line, then transfer the live call to you or your sales team.","image":"/lead-delivery-live-transfer.jpg?v=1"},{"title":"Set a telephone callback appointment?","body":"We schedule a time for you to call them back, or for them to expect your call.","image":"/lead-delivery-callback.jpg?v=1"},{"title":"Set a sit-down appointment?","body":"In-person or virtual sit-downs booked on your calendar with a confirmed date and time.","image":"/lead-delivery-sit-down.jpg?v=1"}]}'::jsonb),
  ('cases', 'Our work stories', 7, '{"pageTitle":"Real calls.","pageIntro":"Stories from the industries we serve. Each one is a calling job, told in plain words.","missing":"Story not found","back":"Back to our work","industryLabel":"Industry","overviewLabel":"Overview","problemLabel":"The problem","didLabel":"What we did","moreTitle":"More of our work","moreBody":"Other calls we made.","items":[{"slug":"kroma","name":"Kroma","date":"2026-03-19T00:00:00.000Z","category":"Final Expense","image":"https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&w=1400&q=80","teaser":"Called families about final expense insurance and booked more times to talk.","overview":"Kroma helps families look at small life insurance plans for final expenses.","industry":"Final Expense Insurance","challengeIntro":"People asked for information, then nobody called them back.","challenge":"Forms came in every day. By the time someone called, the family had moved on or forgotten why they asked. The few calls that did happen used long, confusing words.","strategyIntro":"We called the same day, in plain words.","strategy":"We wrote a short script, trained a small team, and called new requests the day they came in. Callers explained the plan in one sentence and offered a time to talk with a licensed person.","results":[{"label":"more appointments","value":"3.4x"},{"label":"fewer missed calls","value":"42%"},{"label":"people who stayed on the line","value":"5.1 in 10"}]},{"slug":"powersurge","name":"PowerSurge","date":"2025-06-04T00:00:00.000Z","category":"Solar","image":"https://images.unsplash.com/photo-1444012830796-83db7e1db0d3?auto=format&fit=crop&w=1400&q=80","teaser":"Called homeowners about solar and booked more visits to the house.","overview":"PowerSurge puts solar on homes and needed people to show up for a visit.","industry":"Solar","challengeIntro":"Homeowners raised a hand, then went quiet.","challenge":"The company had names of people who wanted a solar quote. Those people did not answer a long email. They needed a short phone call that explained the visit.","strategyIntro":"We called and booked a time at the house.","strategy":"Callers said who they were, explained that a visit is free and takes about an hour, and offered two times. If someone said no, we wrote it down and did not keep pushing.","results":[{"label":"more booked visits","value":"4.2x"},{"label":"jobs from those visits","value":"$1.1M"},{"label":"more people who showed up","value":"38%"}]},{"slug":"asterisk","name":"Asterisk","date":"2025-05-04T00:00:00.000Z","category":"Medicare","image":"https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=1400&q=80","teaser":"Called people with Medicare questions and set more times with an agent.","overview":"Asterisk helps people compare Medicare supplement plans.","industry":"Medicare Supplement","challengeIntro":"Older adults had questions and no one to ask.","challenge":"People wanted a simple answer about their plan. The old calls were fast and full of plan codes. Many folks hung up before they understood the offer.","strategyIntro":"We slowed the call down and used everyday words.","strategy":"The script avoided plan codes. Callers asked what the person already had, explained the next conversation in one sentence, and booked a time with a licensed agent.","results":[{"label":"more good appointments","value":"3x"},{"label":"more people who showed up","value":"47%"},{"label":"more plans started","value":"2.5x"}]},{"slug":"grotesks","name":"Grotesks","date":"2026-03-26T00:00:00.000Z","category":"Business Loans","image":"https://images.unsplash.com/photo-1523398002811-999ca8dec234?auto=format&fit=crop&w=1400&q=80","teaser":"Called shop owners the same day and helped more of them finish a loan request.","overview":"Grotesks finds business loans for shop owners.","industry":"Business Loans","challengeIntro":"Owners filled out a form and never heard back.","challenge":"By the next day, many owners had called a different company. The ones who were reached got a speech they could not follow.","strategyIntro":"We called the same day and walked through one next step.","strategy":"Callers confirmed the business, explained that the next step was a short application, and stayed on the line while the owner started it. If they were busy, we booked a better time.","results":[{"label":"more finished applications","value":"3.8x"},{"label":"more yes answers","value":"52%"},{"label":"shorter calls","value":"24%"}]}]}'::jsonb),
  ('why', 'Why us', 8, '{"tag":"Why Choose Us","title":"Why Choose Phone Hustlers?","subtitle":"American Understanding with the Filipino Drive.","body":"My name is Jay, and I grew up in Atlanta, Georgia. Having lived in the United States, I understand American business culture firsthand. I know how businesses operate overseas, how customers communicate, and, most importantly, how they expect to be treated.\n\nWith over 15 years of experience in the BPO industry, I bring my American background and business knowledge together with the hard work and dedication of my team in the Philippines. To me, great customer service is more than just reading a script. It''s about understanding people, building trust, and making sure every customer has a positive experience with your business.","signName":"Jay Bendebel","signRole":"Founder & CEO","button":"Book a Call","photoRight":"/jay-bendebel.jpg?v=1"}'::jsonb),
  ('industries', 'Industries we serve', 9, '{"title":"Industries We Serve","items":["Merchant Cash Advance","Health Insurance","Business Insurance (GL & WC)","Life Insurance","Final Expense Insurance","Auto Insurance","Medical Alert","Travel/Vacation","Solar","Roofing","HVAC","Home Improvement","Plumbing","Medicare","Business Loans"]}'::jsonb),
  ('process', 'How we work', 10, '{"tag":"Process","title":"5 simple steps to get started!","body":"From your first conversation with us to live dialing on your list.","steps":[{"title":"Learn the offer","body":"We learn what you sell, who it is for, and what a good call sounds like."},{"title":"Write the words","body":"We write a short script. Greeting, one clear offer, two questions, and a way to book a time."},{"title":"Train the callers","body":"The team practices until the call feels natural. If they stumble, we fix the words."},{"title":"Make the calls","body":"We load your list into VICIdial. The dialer rings the numbers. A caller starts talking when a person picks up."},{"title":"Show the results","body":"Each week you see who answered, who booked, and who said no."}],"closeTitle":"Ready for more appointments?","closeButton":"Get Started","rating":"4.9/5","clients":"100+ companies we call for"}'::jsonb),
  ('testimonials', 'What companies say', 11, '{"tag":"Testimonials","title":"What companies say about us","items":[{"quote":"Our booked visits more than doubled. People finally understood the solar offer because someone explained it out loud.","name":"James Walker","role":"Owner, solar company","image":"https://images.unsplash.com/photo-1560250097-0b93528c311a?auto=format&fit=crop&w=900&q=80","video":false,"videoUrl":""},{"quote":"","name":"John Conti","role":"Owner, Trade Show Collections","image":"","video":true,"videoUrl":"/testimonials-john-conti.mp4?v=1"},{"quote":"Within a few weeks we had a steady list of people ready to talk about a loan. The calls were clear and never pushy.","name":"Michael Turner","role":"Owner, business loans","image":"https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?auto=format&fit=crop&w=900&q=80","video":false,"videoUrl":""}]}'::jsonb),
  ('pricing', 'Pricing', 12, '{"tag":"Pricing","title":"Simple, affordable plans","fade":"made for every business","plan":"Calling Team","body":"A trained group on VICIdial, calling for your business every day.","price":"$6,000","period":"/Monthly","button":"Book a Call","includes":"Includes","features":["VICIdial on every shift","Hundreds of calls from each caller","A team that learns your offer","A short script in plain words","Notes after each call","Appointments put on your calendar","A simple weekly report"]}'::jsonb),
  ('faq', 'Questions', 13, '{"tag":"FAQ","title":"Questions people ask first","items":[{"q":"How many calls can one person make?","a":"A minimum of 800 calls per 8-hour shift."},{"q":"Do you only make phone calls?","a":"Yes. Phone Hustlers is a call center. VICIdial dials. We talk, we listen, and we book the next step."},{"q":"Who do you call for?","a":"Companies in the industries on this site, like insurance, loans, solar, medical alert, and home services."},{"q":"Do I need my own dialer or my own callers?","a":"No. We bring VICIdial and the callers. You tell us the offer and give us the list."},{"q":"What happens on a call?","a":"We say who we are, explain the offer in one or two sentences, answer questions, and ask if they want a time to talk more."}]}'::jsonb),
  ('teamHome', 'Home team', 14, '{"tag":"Team","title":"The team on the phones","items":[{"name":"Jay Bendebel","role":"Founder & CEO","image":"/jay-benz.jpg"},{"name":"Paul Bacay","role":"Director of Operations","image":"/director-of-operations.jpg"},{"name":"Sofia Bennett","role":"Head of the Calling Team","image":"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=800&q=80"},{"name":"Marcus Ellery","role":"Script Writer","image":"https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?auto=format&fit=crop&w=800&q=80"},{"name":"Elena Cross","role":"Call Quality Lead","image":"https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=800&q=80"},{"name":"Isabella Reed","role":"Client Care","image":"https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=800&q=80"},{"name":"Camila Torres","role":"Office Manager","image":"https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=crop&w=800&q=80"}]}'::jsonb),
  ('articles', 'Articles', 15, '{"pageTitle":"Simple notes on better calls","pageIntro":"Short lessons from our call center and the leads we help you win.","missing":"Article not found","back":"Back to articles","items":[{"slug":"what-a-predictive-dialer-does","title":"How Our Predictive Dialer Works","date":"2026-03-02T23:00:00.000Z","image":"/filipino-call-center.jpg?v=1","alt":"Phone Hustlers calling team on headsets","body":"A normal phone wastes the shift. The caller waits through rings, busy signals, and voicemail.\n\nOur predictive dialer calls many numbers at the same time.\n\nA caller only hears a voice when a real person picks up.\n\nThat is why one rep can make hundreds of calls in a single shift.\n\nMore talk time means more people hear the offer, and more of them book the next step."},{"slug":"why-people-hang-up","title":"Why People Hang Up","date":"2026-02-11T23:00:00.000Z","image":"https://images.unsplash.com/photo-1553877522-43269d4ea984?auto=format&fit=crop&w=1200&q=80","alt":"Call center agents at work","body":"People hang up when the first sentence is confusing.\n\nSay three things, then stop talking:\n\nWho you are\n\nWhy you called\n\nWhat happens next\n\nIf the caller has to think too hard, the person on the other end will hang up.\n\nThis is true for insurance, loans, solar, and every other industry we call for."},{"slug":"a-script-anyone-can-follow","title":"A Script Anyone Can Follow","date":"2026-02-04T23:00:00.000Z","image":"https://images.unsplash.com/photo-1556761175-5973dc0f32e7?auto=format&fit=crop&w=1200&q=80","alt":"Team reviewing call scripts together","body":"A good script is short.\n\nIt has four parts:\n\nA greeting\n\nThe offer in one sentence\n\nTwo easy questions\n\nA way to book a time\n\nWe write a different script for each industry. A Medicare call should not sound like a solar call.\n\nIf a line feels stiff, we change it until a caller can say it out loud without reading."},{"slug":"call-the-right-people","title":"Call the Right People","date":"2026-01-07T23:00:00.000Z","image":"https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1200&q=80","alt":"Smartphone with lead notification from a call","body":"A long call list is not a good call list.\n\nWe only call people who might want the offer.\n\nA homeowner might want solar. A shop owner might want a business loan. A grandparent might want a medical alert.\n\nCalling the wrong person wastes their time and yours.\n\nBefore the first dial, we agree on who belongs on the list."},{"slug":"what-a-good-call-sounds-like","title":"What a Good Call Sounds Like","date":"2025-12-28T23:00:00.000Z","image":"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=1200&q=80","alt":"Caller on a headset having a conversation","body":"A good call is calm.\n\nSlow voice. Short sentences. No pushy words.\n\nAnswer the question they asked. Then ask if they want a time on the calendar.\n\nA clear no is a good result. It means we did not waste the next appointment.\n\nA booked time is a better result. That is the job."},{"slug":"tell-the-company-the-truth","title":"Tell the Company the Truth","date":"2025-12-16T23:00:00.000Z","image":"https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=1200&q=80","alt":"Weekly call results on a dashboard","body":"Every week we share three numbers.\n\nHow many people answered.\n\nHow many booked a time.\n\nHow many said no.\n\nWe do not hide the nos. They show us which sentence to fix.\n\nSimple numbers help you decide what to do next."}]}'::jsonb),
  ('aboutPage', 'About page', 16, '{"title":"About us.","intro":"Stop dialing one number at a time. Our automated calling system handles hundreds of calls per shift, helping you maximize your return on investment.","button":"Book a Call","storyTag":"Why Choose Us","story":"My name is Jay, and I grew up in Atlanta, Georgia. Having lived in the United States, I understand American business culture firsthand.","missionTag":"Our Mission","missionTitle":"Turn More Conversations Into Customers","mission":"Every call is an opportunity to grow your business. We focus on reaching the right people, building meaningful connections, and turning promising conversations into real opportunities.","teamTag":"Team","teamTitle":"The team on the phones","teamBody":"Every business is different. We take the time to understand your goals, reach the right audience, and create an approach that works for your business.","team":[{"name":"Jay Bendebel","role":"Founder & CEO","image":"/jay-benz.jpg"},{"name":"Paul Bacay","role":"Director of Operations","image":"/director-of-operations.jpg"},{"name":"Sofia Bennett","role":"Head of the Calling Team","image":"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=800&q=80"},{"name":"Marcus Ellery","role":"Script Writer","image":"https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?auto=format&fit=crop&w=800&q=80"},{"name":"Elena Cross","role":"Call Quality Lead","image":"https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=800&q=80"},{"name":"Isabella Reed","role":"Client Care","image":"https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=800&q=80"},{"name":"Camila Torres","role":"Office Manager","image":"https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=crop&w=800&q=80"}]}'::jsonb),
  ('notFound', 'Missing page', 17, '{"code":"404","message":"This page is not here. Letâ€™s go back home.","button":"Back to Home"}'::jsonb)
on conflict (id) do nothing;
